\begin{proof}

The conclusion in the case $d=0$ is simply $\E_{y}[f(y)]^{2}\leq \lambda_{1}^{2}$, which holds by the $L^1$-globalness assumption. We proceed by an induction on $d$. 
Towards this end, fix $d\geq 1$ and assume that the statement holds for all $d'<d$.

Fix $S\neq \emptyset$, so that by \Cref{cor:globalness-of-derivative} we know that $D_{S}f$ is both $(r,r^{|S|}\lambda_{1},d-|S|)$-$L^{1}$-global and $(r,r^{|S|}\lambda_{2},d-|S|)$-$L^{2}$-global. 
Our first goal 
will be to show that $P_{\calC}^{=d}[f]$ has discrete derivatives with small norms, and towards this end we use the induction hypothesis. 
Since $|U|-2|S|\geq 10(m-|S|)$ and $m-|S|\geq 10(d-|S|+1)$, we can apply the induction hypothesis on $D_{S}[f]:\Omega^{U,m}_{\setminus S}\rightarrow \mathbb{R}$. Combining with \Cref{lem:derivative-projection-commute}, we get
\begin{align}
\left\|D_{S}P_{\calC}^{=d}[f]\right\|_{2}^{2}&= \left\|P_{\calC}^{=d-|S|}D_{S}[f]\right\|_{2}^{2}\\
&\leq r^{2|S|}\lambda_{1}^{2}\left(\frac{10^{5}r^{2}\log(\lambda_{2}/\lambda_{1})}{d-|S|}\right)^{d-|S|}\nonumber\\
&= 10^{5(d-|S|)}\lambda_{1}^{2}r^{2d}\log^{d-|S|}(\lambda_{2}/\lambda_{1})d^{-(d-|S|)}\left(1+\frac{|S|}{d-|S|}\right)^{d-|S|}\nonumber\\
&\leq 10^{5(d-|S|)}\lambda_{1}^{2}r^{2d}\log^{d-|S|}(\lambda_{2}/\lambda_{1})d^{-(d-|S|)}\cdot 10^{5|S|}\nonumber\\
&= \lambda_{1}^{2}\left(\frac{10^{5}r^{2}\log(\lambda_{2}/\lambda_{1})}{d}\right)^{d}\left(\frac{\sqrt{d}}{\log^{1/2}(\lambda_{2}/\lambda_{1})}\right)^{2|S|}\notag\\
&=(r')^{2|S|}(\lambda')^{2},\label{eq:globalness-of-level-d}
 \end{align}
 where we let 
\[\lambda'=\lambda_{1}\left(\frac{10^{5}r^{2}\log(\lambda_{2}/\lambda_{1})}{d}\right)^{d/2}\quad\text{ and }\quad
r'=\frac{\sqrt{d}}{\log^{1/2}(\lambda_{2}/\lambda_{1})}.
\]
We intend to apply~\Cref{lem:derivative-based-inequality}, and for that we pick
\[q=\left\lfloor\frac{4\log (\lambda_{2}/\lambda_{1})}{d}\right\rfloor\quad\text{ and }\quad\rho=  \frac{1}{4\sqrt{2}}\min\left\{ q^{-1/2},q^{-1}(r')^{-\frac{q-1}{q}}\right\}.\]
This choice of parameters ensure that $\rho^{-2}\leq 10^{3}q$, and thus
\begin{align}
2^{d}\rho^{-2dq}\lambda_{1}^{2q}\left(\lambda_{2}/\lambda_{1}\right)^{2} &\leq \lambda_{1}^{2q}\left(2\rho^{-2}(\lambda_{2}/\lambda_{1})^{2/(dq)}\right)^{dq}\leq \lambda_{1}^{2q}(10^{4}q)^{dq}\nonumber\\
&\leq \lambda_{1}^{2q}\left(\frac{10^{5}r^{2}\log(\lambda_{2}/\lambda_{1})}{d}\right)^{dq}=(\lambda')^{2q}.\label{eq:parameter-mess-to-lambda}
\end{align}
Since $P_{\calC}^{=d}$ is an orthogonal projection, we have
\begin{align*}
\left\|P_{\calC}^{=d}f\right\|_{2}^{4q}
=\left\langle f,P_{\calC}^{=d}f\right\rangle^{2q}
&\leq \left\|P_{\calC}^{=d}f\right\|_{2q}^{2q}\cdot \|f\|_{2q/(2q-1)}^{2q}\\
&\leq \left\|P_{\calC}^{=d}f\right\|_{2q}^{2q}\cdot \|f\|_{1}^{2q-2}\cdot \|f\|_{2}^{2}\\
&\leq 2^{d}\rho^{-2dq}\lambda_{1}^{2q-2}\lambda_{2}^{2}\left\|P_{\calC}^{=d}f\right\|_{2}^{2}\cdot \max_{S\in\calM_{U,\leq d}}\left((r')^{-|S|}\left\|D_{S}P_{\calC}^{=d}f\right\|_{2}\right)^{2q-2}\\
&\leq (\lambda')^{2q}\cdot\left\|P_{\calC}^{=d}f\right\|_{2}^{2}\max\left(\left\|P_{\calC}^{=d}f\right\|_{2}^{2q-2},(\lambda')^{2q-2}\right),
\end{align*}
where the second and third transitions are by H\"{o}lder's inequality, the fourth transition is by~\Cref{lem:derivative-based-inequality}, and the last transition is by 
\eqref{eq:parameter-mess-to-lambda} and \eqref{eq:globalness-of-level-d}. It follows that $\left\|P_{\calC}^{=d}f\right\|_{2}\leq \lambda'$, as desired.
\end{proof}
